package app.metrolife;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.io.IOException;
import java.util.*;

/** Shared footprint collision and server-time speed budget, independent of render rate. */
final class Navigation {
 final GameService g;final JsonNode data;
 final Map<String,Long> times=new HashMap<>();final Map<String,Double> credits=new HashMap<>();
 Navigation(GameService g){this.g=g;try(var in=getClass().getResourceAsStream("/static-data/navigation.json")){data=g.mapper.readTree(in);}catch(IOException e){throw new IllegalStateException("Navigation data missing",e);}}
 JsonNode city(String city){return data.path("cities").path(city);}
 JsonNode door(ObjectNode s,String place){return place.equals("home")?city(s.path("city").asText()).path("homes").path(s.path("home").path("neighborhood").asText()):city(s.path("city").asText()).path("doors").path(place);}
 ObjectNode position(ObjectNode s){String place=s.path("loc").asText();if(!s.path("position").isObject()||!s.path("position").path("place").asText().equals(place)||!s.path("position").path("city").asText().equals(s.path("city").asText())){JsonNode d=door(s,place);ObjectNode p=s.putObject("position").put("x",d.path("x").asDouble()).put("z",d.path("z").asDouble()).put("face",Math.PI).put("place",place).put("city",s.path("city").asText()).putNull("room");String key=s.path("worldId").asText()+s.path("userId").asText();times.put(key,g.now());credits.put(key,2.4);return p;}return (ObjectNode)s.path("position");}
 static boolean polygon(double x,double z,JsonNode poly){boolean inside=false;for(int i=0,j=poly.size()-1;i<poly.size();j=i++){JsonNode a=poly.get(i),b=poly.get(j);double ax=a.get(0).asDouble(),az=a.get(1).asDouble(),bx=b.get(0).asDouble(),bz=b.get(1).asDouble();if((az>z)!=(bz>z)&&x<(bx-ax)*(z-az)/(bz-az)+ax)inside=!inside;}return inside;}
 static boolean box(double x,double z,JsonNode b,double pad){double dx=x-b.path("x").asDouble(),dz=z-b.path("z").asDouble(),a=b.path("a").asDouble(),c=Math.cos(a),s=Math.sin(a);return Math.abs(dx*c-dz*s)<b.path("w").asDouble()/2+pad&&Math.abs(dx*s+dz*c)<b.path("d").asDouble()/2+pad;}
 boolean stand(String city,double x,double z,String room){if(!room.isEmpty())return Math.abs(x)<5.5&&Math.abs(z)<4.5;JsonNode n=city(city);boolean land=false;for(JsonNode p:n.path("land"))if(polygon(x,z,p))land=true;for(JsonNode b:n.path("bridges"))if(box(x,z,b,-.35))land=true;if(!land)return false;for(JsonNode p:n.path("water"))if(polygon(x,z,p))return false;for(JsonNode b:n.path("boxes"))if(box(x,z,b,.3))return false;return true;}
 ObjectNode move(String token,JsonNode b){ObjectNode ses=g.session(token,true),s=g.sim(ses),w=g.world(ses);g.decay(s,w);ObjectNode p=position(s);GameService.require(s.path("busyUntil").isNull()&&s.path("pendingBeat").isNull(),409,"Finish this moment before walking");GameService.require(b.path("city").asText().equals(s.path("city").asText()),409,"You are in a different city");double x=b.path("x").asDouble(Double.NaN),z=b.path("z").asDouble(Double.NaN),face=b.path("face").asDouble(Double.NaN);GameService.require(Double.isFinite(x)&&Double.isFinite(z)&&Double.isFinite(face),400,"Send a finite position");String key=s.path("worldId").asText()+s.path("userId").asText();long at=g.now();double budget=Math.min(3,credits.getOrDefault(key,0d)+Math.max(0,at-times.getOrDefault(key,at))*.0075),distance=Math.hypot(x-p.path("x").asDouble(),z-p.path("z").asDouble());times.put(key,at);credits.put(key,budget);GameService.require(distance<=budget+1e-6,409,"That is faster than running");int steps=Math.max(1,(int)Math.ceil(distance/.15));for(int i=1;i<=steps;i++){double t=(double)i/steps;GameService.require(stand(s.path("city").asText(),p.path("x").asDouble()+(x-p.path("x").asDouble())*t,p.path("z").asDouble()+(z-p.path("z").asDouble())*t,p.path("room").asText("")),409,"The path is blocked");}credits.put(key,budget-distance);p.put("x",x).put("z",z).put("face",face);if(p.path("room").isNull()){String near="street";double best=3;Iterator<String> ids=city(s.path("city").asText()).path("doors").fieldNames();while(ids.hasNext()){String id=ids.next();JsonNode d=door(s,id);double d2=Math.hypot(d.path("x").asDouble()-x,d.path("z").asDouble()-z);if(d2<best){best=d2;near=id;}}if(s.path("home").path("city").equals(s.path("city"))){JsonNode d=door(s,"home");if(Math.hypot(d.path("x").asDouble()-x,d.path("z").asDouble()-z)<best)near="home";}s.put("loc",near);p.put("place",near);}g.community.online.put(s.path("worldId").asText()+":"+s.path("userId").asText(),at);ObjectNode out=g.object();out.set("position",p.deepCopy());out.put("now",at);return out;}
}
